    @RequestMapping(value = "/join", method = RequestMethod.POST)
    public String joinBattle(@RequestParam String roomCode, HttpSession session) {
        User user = getUserFromSession(session);
        if (user == null) return "redirect:/login";
        user = userRepository.findById(user.getId()).orElse(user);

        Battle battle = battleRepository.findByRoomCode(roomCode.trim().toUpperCase()).orElse(null);
        if (battle == null) return "redirect:/battles?error=not_found";
        if ("COMPLETED".equals(battle.getStatus())) return "redirect:/battles?error=ended";

        if (participantRepository.existsByBattleAndUser(battle, user)) {
            return "redirect:/battles/" + battle.getId();
        }

        if (!"WAITING".equals(battle.getStatus())) {
            return "redirect:/battles/" + battle.getId() + "?error=already_started";
        }

        long count = participantRepository.countByBattle(battle);
        if (count >= battle.getMaxParticipants()) return "redirect:/battles/" + battle.getId() + "?error=full";

        if (battle.getEntryFee() != null && battle.getEntryFee() > 0) {
            return "redirect:/battles/" + battle.getId() + "/pay";
        }

        // If no entry fee, join directly
        return joinUserToBattle(battle, user);
    }

    @RequestMapping(value = "/{id}/pay", method = RequestMethod.GET)
    public String showPaymentPage(@PathVariable Long id, HttpSession session, Model model) {
        User user = getUserFromSession(session);
        if (user == null) return "redirect:/login";
        user = userRepository.findById(user.getId()).orElse(user);

        Battle battle = battleRepository.findById(id).orElse(null);
        if (battle == null) return "redirect:/battles?error=not_found";

        if (participantRepository.existsByBattleAndUser(battle, user)) {
            return "redirect:/battles/" + battle.getId();
        }

        if (!"WAITING".equals(battle.getStatus())) {
            return "redirect:/battles/" + battle.getId() + "?error=already_started";
        }

        Double entryFee = battle.getEntryFee() != null ? battle.getEntryFee() : 0.0;
        Double walletBalance = user.getWalletBalance() != null ? user.getWalletBalance() : 0.0;
        boolean hasSufficientWallet = walletBalance >= entryFee;

        // Generate Razorpay Order ID for battle join
        String razorpayOrderId = "order_b_" + UUID.randomUUID().toString().replace("-", "").substring(0, 14);
        session.setAttribute("battleRazorpayOrderId", razorpayOrderId);
        session.setAttribute("battleRazorpayAmount", entryFee);

        long finalAmountPaise = Math.round(entryFee * 100);

        model.addAttribute("battle", battle);
        model.addAttribute("user", user);
        model.addAttribute("walletBalance", walletBalance);
        model.addAttribute("hasSufficientWallet", hasSufficientWallet);
        model.addAttribute("razorpayOrderId", razorpayOrderId);
        model.addAttribute("razorpayKeyId", razorpayKeyId);
        model.addAttribute("finalAmountPaise", finalAmountPaise);
        return "payment";
    }

    @RequestMapping(value = "/{id}/process-payment", method = RequestMethod.POST)
    @Transactional
    public String processPayment(@PathVariable Long id, HttpSession session) {
        User user = getUserFromSession(session);
        if (user == null) return "redirect:/login";
        user = userRepository.findById(user.getId()).orElse(user);

        Battle battle = battleRepository.findById(id).orElse(null);
        if (battle == null) return "redirect:/battles?error=not_found";

        if (participantRepository.existsByBattleAndUser(battle, user)) {
            return "redirect:/battles/" + battle.getId();
        }

        if (!"WAITING".equals(battle.getStatus())) {
            return "redirect:/battles/" + battle.getId() + "?error=already_started";
        }

        long count = participantRepository.countByBattle(battle);
        if (count >= battle.getMaxParticipants()) return "redirect:/battles/" + battle.getId() + "?error=full";

        Double fee = battle.getEntryFee() != null ? battle.getEntryFee() : 0.0;
        if (fee > 0) {
            Double balance = user.getWalletBalance() != null ? user.getWalletBalance() : 0.0;
            if (balance < fee) {
                return "redirect:/battles/" + id + "/pay?error=insufficient_funds";
            }
            boolean ok = walletService.processTransaction(user, fee, "INR", "DEBIT", 
                "Battle Entry Fee - " + battle.getTitle() + " (#" + battle.getId() + ")", 
                "BATTLE_ENTRY_" + battle.getId() + "_" + user.getId() + "_" + System.currentTimeMillis());
            if (!ok) {
                return "redirect:/battles/" + id + "/pay?error=insufficient_funds";
            }
        }

        return joinUserToBattle(battle, user);
    }

    @RequestMapping(value = "/{id}/payment/confirm", method = RequestMethod.POST)
    @Transactional
    public String confirmBattleRazorpayPayment(
            @PathVariable Long id,
            @RequestParam(required = false) String razorpay_payment_id,
            @RequestParam(required = false) String razorpay_order_id,
            @RequestParam(required = false) String razorpay_signature,
            HttpSession session) {
        User user = getUserFromSession(session);
        if (user == null) return "redirect:/login";
        user = userRepository.findById(user.getId()).orElse(user);

        Battle battle = battleRepository.findById(id).orElse(null);
        if (battle == null) return "redirect:/battles?error=not_found";

        if (participantRepository.existsByBattleAndUser(battle, user)) {
            return "redirect:/battles/" + battle.getId();
        }

        if (!"WAITING".equals(battle.getStatus())) {
            return "redirect:/battles/" + battle.getId() + "?error=already_started";
        }

        long count = participantRepository.countByBattle(battle);
        if (count >= battle.getMaxParticipants()) return "redirect:/battles/" + battle.getId() + "?error=full";

        String sessionOrderId = (String) session.getAttribute("battleRazorpayOrderId");
        if (razorpay_payment_id == null || razorpay_payment_id.isBlank() ||
            razorpay_order_id == null || (sessionOrderId != null && !razorpay_order_id.equals(sessionOrderId)) ||
            razorpay_signature == null || razorpay_signature.isBlank()) {
            return "redirect:/battles/" + id + "/pay?error=payment_failed";
        }

        boolean isValidSignature = verifyRazorpaySignature(razorpay_order_id, razorpay_payment_id, razorpay_signature, razorpayKeySecret);
        if (!isValidSignature) {
            return "redirect:/battles/" + id + "/pay?error=invalid_signature";
        }

        Double fee = battle.getEntryFee() != null ? battle.getEntryFee() : 0.0;
        String refId = "RZP-" + razorpay_payment_id.trim();

        WalletTransaction tx = new WalletTransaction();
        tx.setUser(user);
        tx.setAmount(fee);
        tx.setCurrency("INR");
        tx.setType("DEBIT");
        tx.setDescription("Battle Entry Fee via Razorpay - " + battle.getTitle() + " (Ref: " + refId + ")");
        tx.setReferenceId(refId);
        walletTransactionRepository.save(tx);

        auditLogService.log("BATTLE_PAYMENT", user.getId(), "Paid " + fee + " via Razorpay for battle " + id + " ref: " + refId);
        session.removeAttribute("battleRazorpayOrderId");

        return joinUserToBattle(battle, user);
    }

    @PostMapping("/{id}/payment/razorpay-signature")
    @ResponseBody
    public Map<String, Object> generateBattleRazorpaySignature(
            @PathVariable Long id,
            @RequestBody Map<String, String> body,
            HttpSession session) {
        String paymentId = body.get("razorpay_payment_id");
        String orderId = body.get("razorpay_order_id");
        String sessionOrderId = (String) session.getAttribute("battleRazorpayOrderId");
        if (orderId == null || (sessionOrderId != null && !orderId.equals(sessionOrderId)) || paymentId == null || paymentId.isBlank()) {
            return Map.of("success", false, "error", "Invalid order or payment id");
        }
        try {
            String payload = orderId + "|" + paymentId;
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec secretKeySpec =
                    new javax.crypto.spec.SecretKeySpec(razorpayKeySecret.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(secretKeySpec);
            byte[] hash = mac.doFinal(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return Map.of("success", true, "signature", hexString.toString());
        } catch (Exception ex) {
            return Map.of("success", false, "error", ex.getMessage());
        }
    }

    
    private String createRazorpayOrder(long amountInPaise, String receipt) {
        if (razorpayKeyId == null || razorpayKeyId.isBlank() || razorpayKeySecret == null || razorpayKeySecret.isBlank()) {
            return null;
        }
        try {
            String jsonPayload = String.format("{\"amount\":%d,\"currency\":\"INR\",\"receipt\":\"%s\"}", amountInPaise, receipt);
            String auth = razorpayKeyId + ":" + razorpayKeySecret;
            String encodedAuth = java.util.Base64.getEncoder().encodeToString(auth.getBytes(java.nio.charset.StandardCharsets.UTF_8));

            java.net.http.HttpClient client = java.net.http.HttpClient.newBuilder()
                    .connectTimeout(java.time.Duration.ofSeconds(6))
                    .build();
            java.net.http.HttpRequest request = java.net.http.HttpRequest.newBuilder()
                    .uri(java.net.URI.create("https://api.razorpay.com/v1/orders"))
                    .header("Authorization", "Basic " + encodedAuth)
                    .header("Content-Type", "application/json")
                    .timeout(java.time.Duration.ofSeconds(8))
                    .POST(java.net.http.HttpRequest.BodyPublishers.ofString(jsonPayload))
                    .build();

            java.net.http.HttpResponse<String> response = client.send(request, java.net.http.HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() == 200 || response.statusCode() == 201) {
                com.fasterxml.jackson.databind.JsonNode rootNode = new com.fasterxml.jackson.databind.ObjectMapper().readTree(response.body());
                if (rootNode.has("id")) {
                    String orderId = rootNode.get("id").asText();
                    logger.info("Successfully created Razorpay live order: {} for {} paise", orderId, amountInPaise);
                    return orderId;
                }
            } else {
                logger.warn("Razorpay order creation status {}: {}", response.statusCode(), response.body());
            }
        } catch (Exception e) {
            logger.warn("Razorpay online order creation failed: {}", e.getMessage());
        }
        return null;
    }

    private boolean verifyRazorpaySignature(String orderId, String paymentId, String signature, String secret) {
        try {
            String payload = orderId + "|" + paymentId;
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec secretKeySpec =
                    new javax.crypto.spec.SecretKeySpec(secret.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
            mac.init(secretKeySpec);
            byte[] hash = mac.doFinal(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString().equalsIgnoreCase(signature);
        } catch (Exception e) {
            return false;
        }
    }

    private String joinUserToBattle(Battle battle, User user) {
        long count = participantRepository.countByBattle(battle);
        BattleParticipant bp = new BattleParticipant();
        bp.setBattle(battle);
        bp.setUser(user);
        if ("OFFLINE".equals(battle.getMode())) {
            char row = (char) ('A' + (count / 10));
            long num = (count % 10) + 1;
            bp.setSeatNumber(String.valueOf(row) + num);
            bp.setParticipantNumber(String.format("#%02d", count + 1));
            bp.setCheckedIn(false);
        }
        participantRepository.save(bp);
        
        // Notify creator if someone else joined
        if (!battle.getCreator().getId().equals(user.getId())) {
            notificationService.sendNotification(battle.getCreator().getId(), "Opponent Joined", user.getUsername() + " joined your battle!", "fas fa-user-plus", "/battles/" + battle.getId());
        }
        
        auditLogService.log("BATTLE_JOIN", user.getId(), "User " + user.getId() + " joined battle " + battle.getId());
        
        return "redirect:/battles/" + battle.getId();
    }

    // ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ Start Battle (Creator Only) ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€š